import { useState } from 'react';
import { JxTagInput, JxChip, JxEmptyState } from '@jinx-ui/react';

interface ArticleTagsPickerProps {
  label?: string;
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagsPicker({
  label = 'Теги статьи',
  defaultTags = [],
  onChange,
}: ArticleTagsPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const update = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <JxTagInput
        ariaLabel={label}
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={update}
      />

      {tags.length === 0 ? (
        <JxEmptyState
          title="Тегов пока нет"
          message="Введите слово в поле выше и нажмите Enter, чтобы добавить первый тег."
        />
      ) : (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <span role="listitem" key={tag} style={{ maxWidth: '100%' }}>
              <JxChip
                active
                removable
                onRemove={() => update(tags.filter((item) => item !== tag))}
              >
                {tag}
              </JxChip>
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

